import{_ as e,c as o,o as r,ak as a}from"./chunks/framework.gmyagHYt.js";const g=JSON.parse('{"title":"服务隐私政策","description":"","frontmatter":{"title":"服务隐私政策","sidebar":false},"headers":[],"relativePath":"service-privacy/index.md","filePath":"service-privacy/index.md","contributors":[{"name":"晚安","username":"nulijiazaizhong","avatar":"https://github.com/nulijiazaizhong.png?size=64","commits":1,"profileUrl":"https://github.com/nulijiazaizhong"}]}'),n={name:"service-privacy/index.md"};function s(i,t,d,l,c,h){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="中文" tabindex="-1">中文 <a class="header-anchor" href="#中文" aria-label="Permalink to “中文”">​</a></h1><h2 id="服务隐私政策" tabindex="-1">服务隐私政策 <a class="header-anchor" href="#服务隐私政策" aria-label="Permalink to “服务隐私政策”">​</a></h2><p>版本：v1.0<br> 生效日期：2026年11月1日<br> 最后更新：2026年11月1日</p><p><strong>导言</strong></p><p><a href="https://ets2la.cn/" target="_blank" rel="noreferrer">ets2la.cn</a>（以下称“本网站”）是 ETS2LA 项目的中国镜像站。本网站由个人运营者 <strong>goodnightan</strong>（以下称“我们”）独立运营，与境外站点 <code>ets2la.com</code> 的运营方相区分。我们依据《中华人民共和国个人信息保护法》（PIPL）、《促进和规范数据跨境流动规定》及《小型个人信息处理者个人信息保护简化措施规定》等适用规定处理您的个人信息。</p><p>本政策说明我们收集哪些信息、如何使用、是否向境外提供，以及您如何行使权利。<strong>请您特别关注第3条“个人信息跨境传输”</strong>——账户数据在您使用本网站时会同步至境外站点，该条包含您作出单独同意所必需的全部告知内容。</p><h3 id="_1-我们是谁" tabindex="-1">1. 我们是谁 <a class="header-anchor" href="#_1-我们是谁" aria-label="Permalink to “1. 我们是谁”">​</a></h3><p><strong>个人信息处理者：</strong> goodnightan（个人），<a href="https://ets2la.cn/" target="_blank" rel="noreferrer">ets2la.cn</a> 的运营者。</p><p><strong>联系方式：</strong> <a href="mailto:support@ets2la.cn" target="_blank" rel="noreferrer">support@ets2la.cn</a></p><p>我们是本网站所服务流量的<strong>独立个人信息处理者</strong>。<code>ets2la.com</code> 由另一运营方在中华人民共和国境外独立运营，其个人信息处理活动适用其自身的隐私政策，不适用本政策。我们与 <code>ets2la.com</code> 运营方共享账户数据库，但各自对所收集的个人信息承担责任。</p><h3 id="_2-我们收集哪些个人信息-以及如何收集" tabindex="-1">2. 我们收集哪些个人信息，以及如何收集 <a class="header-anchor" href="#_2-我们收集哪些个人信息-以及如何收集" aria-label="Permalink to “2. 我们收集哪些个人信息，以及如何收集”">​</a></h3><p>本网站仅收集维持服务运行和账户功能所必需的信息。我们<strong>不收集遥测数据或技术日志</strong>，此类信息仅存储于 <code>ets2la.com</code>。</p><table tabindex="0"><thead><tr><th>信息类别</th><th>具体内容</th><th>来源</th><th>保存期限</th></tr></thead><tbody><tr><td>账户标识</td><td>用户名、用户 ID</td><td>您注册时提供</td><td>账户存续期间</td></tr><tr><td>角色信息</td><td>账户在 ETS2LA 中的角色</td><td>注册时或由系统生成</td><td>账户存续期间</td></tr><tr><td>订阅状态</td><td>订阅是否有效、到期时间</td><td>订阅行为产生</td><td>账户存续期间及订阅到期后合理期间</td></tr></tbody></table><p><strong>我们不处理敏感个人信息</strong>，包括但不限于生物识别、宗教信仰、医疗健康、金融账户、行踪轨迹，以及不满十四周岁未成年人的个人信息。本网站不面向不满十四周岁的未成年人提供服务。</p><h3 id="_3-个人信息跨境传输-请重点阅读" tabindex="-1">3. 个人信息跨境传输（请重点阅读） <a class="header-anchor" href="#_3-个人信息跨境传输-请重点阅读" aria-label="Permalink to “3. 个人信息跨境传输（请重点阅读）”">​</a></h3><h4 id="_3-1-为什么需要跨境传输" tabindex="-1">3.1 为什么需要跨境传输 <a class="header-anchor" href="#_3-1-为什么需要跨境传输" aria-label="Permalink to “3.1 为什么需要跨境传输”">​</a></h4><p>ETS2LA 在中国境内（<code>ets2la.cn</code>）和境外（<code>ets2la.com</code>）使用<strong>同一个账户数据库</strong>。这一设计的目的在于：您无需注册两个账户，且您的订阅状态在中国境内和境外保持一致，不会因您的地理位置变化而中断。</p><p>为维持这一功能，当您使用本网站时，第2条所列的<strong>账户标识、角色和订阅状态</strong>会与 <code>ets2la.com</code> 运营方进行双向同步。<strong>遥测数据和技术日志不在传输范围内</strong>，它们仅存储于 <code>ets2la.com</code>，本网站不收集也不向其传输此类信息。</p><h4 id="_3-2-境外接收方" tabindex="-1">3.2 境外接收方 <a class="header-anchor" href="#_3-2-境外接收方" aria-label="Permalink to “3.2 境外接收方”">​</a></h4><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>名称/姓名</strong></td><td>ETS2LA Developers</td></tr><tr><td><strong>联系方式</strong></td><td><a href="mailto:contact@ets2la.com" target="_blank" rel="noreferrer">contact@ets2la.com</a></td></tr><tr><td><strong>所在国家/地区</strong></td><td>波兰</td></tr><tr><td><strong>处理目的</strong></td><td>维持跨境统一的账户体系与订阅状态，使用户无需重复注册、订阅不因跨境使用而失效</td></tr><tr><td><strong>处理方式</strong></td><td>通过账户数据库进行读取与写入；双向同步</td></tr><tr><td><strong>个人信息种类</strong></td><td>账户标识、角色、订阅状态（<strong>不含</strong>遥测数据、技术日志、敏感个人信息）</td></tr></tbody></table><h4 id="_3-3-法律依据与豁免说明" tabindex="-1">3.3 法律依据与豁免说明 <a class="header-anchor" href="#_3-3-法律依据与豁免说明" aria-label="Permalink to “3.3 法律依据与豁免说明”">​</a></h4><p>根据《促进和规范数据跨境流动规定》，关键信息基础设施运营者以外的数据处理者，自当年1月1日起累计向境外提供<strong>不满10万人</strong>个人信息（不含敏感个人信息）的，<strong>免予</strong>申报数据出境安全评估、订立个人信息出境标准合同及完成备案。本网站目前符合该条件，因此不进行标准合同备案。</p><p>但豁免<strong>不免除</strong>告知与单独同意义务。依据 PIPL 第39条，我们仍须向您告知上述第3.2条的全部事项，并取得您的<strong>单独同意</strong>。同时，我们将在传输前完成个人信息保护影响评估。</p><h4 id="_3-4-如何向我们行使权利-以及如何向境外接收方行使权利" tabindex="-1">3.4 如何向我们行使权利，以及如何向境外接收方行使权利 <a class="header-anchor" href="#_3-4-如何向我们行使权利-以及如何向境外接收方行使权利" aria-label="Permalink to “3.4 如何向我们行使权利，以及如何向境外接收方行使权利”">​</a></h4><p><strong>向我们行使权利：</strong> 通过第1条的联系方式提出，我们将在15个工作日内回应。</p><p><strong>向境外接收方行使权利：</strong> 您可以联系第3.2条所列的 <code>ets2la.com</code> 运营方联系方式，向其提出查阅、更正、删除您账户信息的请求。由于双方共享账户数据库，向其中一方行使权利的效果通常会同步反映在另一方。如境外接收方未在合理期限内回应，您可以告知我们，我们将协助转达或协调，但我们不对境外接收方的独立处理行为承担替代责任。</p><h3 id="_4-我们如何使用您的个人信息" tabindex="-1">4. 我们如何使用您的个人信息 <a class="header-anchor" href="#_4-我们如何使用您的个人信息" aria-label="Permalink to “4. 我们如何使用您的个人信息”">​</a></h3><p>我们仅在以下目的范围内处理第2条所列信息：</p><ul><li>创建和管理您的本网站账户；</li><li>维持您在本网站与 <code>ets2la.com</code> 之间统一的账户标识、角色和订阅状态；</li><li>响应您依据本政策提出的权利请求；</li><li>履行法律法规规定的义务。</li></ul><p><strong>我们不会</strong>将您的个人信息用于用户画像、自动化决策、广告推送或与上述目的无关的任何用途。如未来确需变更处理目的或增加个人信息种类，我们将<strong>重新向您告知并取得单独同意</strong>（涉及跨境传输时）或相应同意。</p><h3 id="_5-我们如何共享、委托处理或公开披露您的个人信息" tabindex="-1">5. 我们如何共享、委托处理或公开披露您的个人信息 <a class="header-anchor" href="#_5-我们如何共享、委托处理或公开披露您的个人信息" aria-label="Permalink to “5. 我们如何共享、委托处理或公开披露您的个人信息”">​</a></h3><p>除第3条所述的跨境同步外，我们<strong>不会</strong>向任何第三方提供、出售或公开披露您的个人信息，法律法规另有强制性规定的除外。</p><p>我们未委托第三方处理您的个人信息。本网站不集成第三方广告SDK、统计分析SDK或其他将个人信息传输至第三方的组件。</p><h3 id="_6-我们如何保护您的个人信息" tabindex="-1">6. 我们如何保护您的个人信息 <a class="header-anchor" href="#_6-我们如何保护您的个人信息" aria-label="Permalink to “6. 我们如何保护您的个人信息”">​</a></h3><p>鉴于本网站的运营规模，我们采取与自身能力相当的简化安全措施：</p><ul><li>账户数据传输采用传输层加密（TLS）；</li><li>账户数据库的访问限于维持服务所必需的凭据和接口；</li><li>我们不存储遥测数据和技术日志，从而从源头减少了可被泄露的信息面；</li><li>一旦发生或可能发生个人信息泄露、篡改、丢失，我们将依据《小型个人信息处理者个人信息保护简化措施规定》的要求，以弹窗公告等简便方式及时通知您，并采取补救措施。</li></ul><h3 id="_7-您的权利" tabindex="-1">7. 您的权利 <a class="header-anchor" href="#_7-您的权利" aria-label="Permalink to “7. 您的权利”">​</a></h3><p>依据 PIPL，您对您的个人信息享有以下权利：</p><table tabindex="0"><thead><tr><th>权利</th><th>内容</th><th>行使方式</th></tr></thead><tbody><tr><td><strong>知情权与决定权</strong></td><td>知悉处理规则，并限制或拒绝处理</td><td>阅读本政策；通过第1条联系方式提出</td></tr><tr><td><strong>查阅、复制权</strong></td><td>查阅、复制您的账户信息</td><td>通过第1条联系方式提出</td></tr><tr><td><strong>更正、补充权</strong></td><td>更正不准确的账户信息</td><td>通过第1条联系方式提出</td></tr><tr><td><strong>删除权</strong></td><td>在法定情形下请求删除</td><td>通过第1条联系方式提出</td></tr><tr><td><strong>撤回同意权</strong></td><td>撤回对跨境传输的单独同意</td><td>通过第1条联系方式提出；撤回不影响撤回前已进行的处理</td></tr></tbody></table><p><strong>关于撤回跨境单独同意的后果：</strong> 由于跨境同步是维持本网站账户功能所必需的，撤回该单独同意将导致我们无法继续向您提供本网站服务。您可以选择停止使用本网站。撤回后，我们将停止将您的信息同步至 <code>ets2la.com</code>，但已完成的同步无法回溯撤销。</p><p>我们将在收到您的权利请求后<strong>15个工作日</strong>内予以回应；情况复杂的，可延长至合理期限并告知您。</p><h3 id="_8-本政策的更新" tabindex="-1">8. 本政策的更新 <a class="header-anchor" href="#_8-本政策的更新" aria-label="Permalink to “8. 本政策的更新”">​</a></h3><p>我们可能因法律变化、服务调整或数据种类变更而更新本政策。更新后的政策将在本网站公布，重大变更（尤其是跨境接收方变更、出境信息种类增加或处理目的变化）将以弹窗或站内公告方式<strong>单独提示</strong>，并在必要时重新取得您的同意。</p><p>如本政策的中文版本与任何翻译版本不一致，以<strong>中文版本</strong>为准。</p><h3 id="_9-联系与投诉" tabindex="-1">9. 联系与投诉 <a class="header-anchor" href="#_9-联系与投诉" aria-label="Permalink to “9. 联系与投诉”">​</a></h3><p>对本政策有任何疑问，或希望行使第7条所列权利，请通过以下方式联系我们：</p><p><strong>电子邮箱：</strong> <a href="mailto:1804832964@qq.com" target="_blank" rel="noreferrer">1804832964@qq.com</a></p><p>如您认为我们的处理活动损害了您的合法权益，您也可以向<strong>所在地省级网信部门</strong>投诉、举报。</p><hr><h1 id="english" tabindex="-1">English <a class="header-anchor" href="#english" aria-label="Permalink to “English”">​</a></h1><h2 id="service-privacy-policy" tabindex="-1">Service Privacy Policy <a class="header-anchor" href="#service-privacy-policy" aria-label="Permalink to “Service Privacy Policy”">​</a></h2><p>Version: v1.0<br> Effective Date: November 1, 2026<br> Last Updated: November 1, 2026</p><p><strong>Introduction</strong></p><p><a href="https://ets2la.cn/" target="_blank" rel="noreferrer">ets2la.cn</a> (hereinafter referred to as the &quot;Website&quot;) is the Chinese mirror site of the ETS2LA project. The Website is independently operated by <strong>goodnightan</strong>, an individual operator (hereinafter referred to as &quot;we&quot; or &quot;us&quot;), and is distinct from the operator of the overseas site <code>ets2la.com</code>. We process your personal information in accordance with applicable laws and regulations, including the Personal Information Protection Law of the People&#39;s Republic of China (PIPL), the Provisions on Promoting and Regulating Cross-Border Data Flows, and the Simplified Measures for Personal Information Protection by Small-Scale Personal Information Processors.</p><p>This Policy explains what information we collect, how we use it, whether it is transferred overseas, and how you may exercise your rights. <strong>Please pay particular attention to Section 3, &quot;Cross-Border Transfer of Personal Information.&quot;</strong> Account data is synchronized with the overseas site when you use the Website. That section contains all the information required for you to provide your separate consent.</p><h3 id="_1-who-we-are" tabindex="-1">1. Who We Are <a class="header-anchor" href="#_1-who-we-are" aria-label="Permalink to “1. Who We Are”">​</a></h3><p><strong>Personal Information Processor:</strong> goodnightan (an individual), operator of <a href="https://ets2la.cn/" target="_blank" rel="noreferrer">ets2la.cn</a>.</p><p><strong>Contact:</strong> <a href="mailto:support@ets2la.cn" target="_blank" rel="noreferrer">support@ets2la.cn</a></p><p>We are the <strong>independent personal information processor</strong> for the traffic served by the Website. <code>ets2la.com</code> is independently operated outside the People&#39;s Republic of China by another operator. Its personal information processing activities are governed by its own privacy policy, not this Policy. We share an account database with the operator of <code>ets2la.com</code>, but each party is responsible for the personal information it collects.</p><h3 id="_2-what-personal-information-we-collect-and-how-we-collect-it" tabindex="-1">2. What Personal Information We Collect and How We Collect It <a class="header-anchor" href="#_2-what-personal-information-we-collect-and-how-we-collect-it" aria-label="Permalink to “2. What Personal Information We Collect and How We Collect It”">​</a></h3><p>The Website collects only the information necessary to maintain service operations and account functionality. We <strong>do not collect telemetry data or technical logs</strong>; such information is stored only on <code>ets2la.com</code>.</p><table tabindex="0"><thead><tr><th>Category</th><th>Specific Information</th><th>Source</th><th>Retention Period</th></tr></thead><tbody><tr><td>Account identifiers</td><td>Username and user ID</td><td>Provided by you during registration</td><td>For the duration of the account</td></tr><tr><td>Role information</td><td>Your account&#39;s role in ETS2LA</td><td>Provided during registration or generated by the system</td><td>For the duration of the account</td></tr><tr><td>Subscription status</td><td>Whether the subscription is active and its expiration date</td><td>Generated by subscription activity</td><td>For the duration of the account and a reasonable period after the subscription expires</td></tr></tbody></table><p><strong>We do not process sensitive personal information</strong>, including but not limited to biometric data, religious beliefs, medical and health information, financial accounts, location tracks, or the personal information of minors under the age of fourteen. The Website does not provide services to minors under the age of fourteen.</p><h3 id="_3-cross-border-transfer-of-personal-information-please-read-carefully" tabindex="-1">3. Cross-Border Transfer of Personal Information (Please Read Carefully) <a class="header-anchor" href="#_3-cross-border-transfer-of-personal-information-please-read-carefully" aria-label="Permalink to “3. Cross-Border Transfer of Personal Information (Please Read Carefully)”">​</a></h3><h4 id="_3-1-why-cross-border-transfer-is-necessary" tabindex="-1">3.1 Why Cross-Border Transfer Is Necessary <a class="header-anchor" href="#_3-1-why-cross-border-transfer-is-necessary" aria-label="Permalink to “3.1 Why Cross-Border Transfer Is Necessary”">​</a></h4><p>ETS2LA uses <strong>the same account database</strong> within China (<code>ets2la.cn</code>) and overseas (<code>ets2la.com</code>). This design means that you do not need to register two accounts, and your subscription status remains consistent within and outside China without interruption due to changes in your geographic location.</p><p>To maintain this functionality, when you use the Website, the <strong>account identifiers, role information, and subscription status</strong> listed in Section 2 are synchronized in both directions with the operator of <code>ets2la.com</code>. <strong>Telemetry data and technical logs are not included in these transfers.</strong> They are stored only on <code>ets2la.com</code>; the Website neither collects nor transfers such information to it.</p><h4 id="_3-2-overseas-recipient" tabindex="-1">3.2 Overseas Recipient <a class="header-anchor" href="#_3-2-overseas-recipient" aria-label="Permalink to “3.2 Overseas Recipient”">​</a></h4><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>ETS2LA Developers</td></tr><tr><td><strong>Contact</strong></td><td><a href="mailto:contact@ets2la.com" target="_blank" rel="noreferrer">contact@ets2la.com</a></td></tr><tr><td><strong>Country/Region</strong></td><td>Poland</td></tr><tr><td><strong>Purpose of Processing</strong></td><td>To maintain a unified cross-border account system and subscription status, so that users do not need to register repeatedly and their subscriptions remain valid when used across borders</td></tr><tr><td><strong>Method of Processing</strong></td><td>Reading from and writing to the account database; bidirectional synchronization</td></tr><tr><td><strong>Categories of Personal Information</strong></td><td>Account identifiers, role information, and subscription status (<strong>excluding</strong> telemetry data, technical logs, and sensitive personal information)</td></tr></tbody></table><h4 id="_3-3-legal-basis-and-exemption" tabindex="-1">3.3 Legal Basis and Exemption <a class="header-anchor" href="#_3-3-legal-basis-and-exemption" aria-label="Permalink to “3.3 Legal Basis and Exemption”">​</a></h4><p>Under the Provisions on Promoting and Regulating Cross-Border Data Flows, a data processor other than a critical information infrastructure operator that has provided the personal information of <strong>fewer than 100,000 individuals</strong> overseas cumulatively since January 1 of the current year (excluding sensitive personal information) is <strong>exempt</strong> from applying for a data export security assessment, entering into a standard contract for the export of personal information, and completing the associated filing. The Website currently meets this condition and therefore does not complete a standard contract filing.</p><p>However, this exemption <strong>does not remove</strong> the obligations to provide notice and obtain separate consent. Under Article 39 of the PIPL, we must still inform you of all the matters listed in Section 3.2 above and obtain your <strong>separate consent</strong>. We will also complete a personal information protection impact assessment before the transfer.</p><h4 id="_3-4-how-to-exercise-your-rights-with-us-and-with-the-overseas-recipient" tabindex="-1">3.4 How to Exercise Your Rights with Us and with the Overseas Recipient <a class="header-anchor" href="#_3-4-how-to-exercise-your-rights-with-us-and-with-the-overseas-recipient" aria-label="Permalink to “3.4 How to Exercise Your Rights with Us and with the Overseas Recipient”">​</a></h4><p><strong>Exercising your rights with us:</strong> Submit a request using the contact details in Section 1. We will respond within 15 business days.</p><p><strong>Exercising your rights with the overseas recipient:</strong> You may contact the operator of <code>ets2la.com</code> using the contact details listed in Section 3.2 to request access to, correction of, or deletion of your account information. Because both parties share the account database, exercising your rights with one party will generally be reflected by the other party as well. If the overseas recipient does not respond within a reasonable period, you may notify us, and we will assist in forwarding or coordinating your request. However, we do not assume substitute liability for the overseas recipient&#39;s independent processing activities.</p><h3 id="_4-how-we-use-your-personal-information" tabindex="-1">4. How We Use Your Personal Information <a class="header-anchor" href="#_4-how-we-use-your-personal-information" aria-label="Permalink to “4. How We Use Your Personal Information”">​</a></h3><p>We process the information listed in Section 2 only for the following purposes:</p><ul><li>Creating and managing your account on the Website;</li><li>Maintaining consistent account identifiers, role information, and subscription status between the Website and <code>ets2la.com</code>;</li><li>Responding to rights requests you submit under this Policy;</li><li>Fulfilling obligations required by laws and regulations.</li></ul><p><strong>We will not</strong> use your personal information for user profiling, automated decision-making, advertising, or any purpose unrelated to those listed above. If it becomes necessary to change the purposes of processing or add categories of personal information in the future, we will <strong>provide renewed notice and obtain your separate consent</strong> (where cross-border transfer is involved) or other appropriate consent.</p><h3 id="_5-how-we-share-entrust-the-processing-of-or-publicly-disclose-your-personal-information" tabindex="-1">5. How We Share, Entrust the Processing of, or Publicly Disclose Your Personal Information <a class="header-anchor" href="#_5-how-we-share-entrust-the-processing-of-or-publicly-disclose-your-personal-information" aria-label="Permalink to “5. How We Share, Entrust the Processing of, or Publicly Disclose Your Personal Information”">​</a></h3><p>Except for the cross-border synchronization described in Section 3, we <strong>will not</strong> provide, sell, or publicly disclose your personal information to any third party, unless otherwise mandated by laws or regulations.</p><p>We do not entrust any third party with processing your personal information. The Website does not integrate third-party advertising SDKs, analytics SDKs, or other components that transmit personal information to third parties.</p><h3 id="_6-how-we-protect-your-personal-information" tabindex="-1">6. How We Protect Your Personal Information <a class="header-anchor" href="#_6-how-we-protect-your-personal-information" aria-label="Permalink to “6. How We Protect Your Personal Information”">​</a></h3><p>Given the scale of the Website&#39;s operations, we implement simplified security measures appropriate to our capabilities:</p><ul><li>Account data is encrypted in transit using Transport Layer Security (TLS);</li><li>Access to the account database is limited to the credentials and interfaces necessary to maintain the service;</li><li>We do not store telemetry data or technical logs, thereby reducing the amount of information that could be exposed at the source;</li><li>If a personal information breach, alteration, or loss occurs or may occur, we will promptly notify you through convenient means such as pop-up announcements, as required by the Simplified Measures for Personal Information Protection by Small-Scale Personal Information Processors, and take remedial measures.</li></ul><h3 id="_7-your-rights" tabindex="-1">7. Your Rights <a class="header-anchor" href="#_7-your-rights" aria-label="Permalink to “7. Your Rights”">​</a></h3><p>Under the PIPL, you have the following rights regarding your personal information:</p><table tabindex="0"><thead><tr><th>Right</th><th>Description</th><th>How to Exercise It</th></tr></thead><tbody><tr><td><strong>Right to know and decide</strong></td><td>Know the processing rules and restrict or refuse processing</td><td>Read this Policy; submit a request using the contact details in Section 1</td></tr><tr><td><strong>Right to access and copy</strong></td><td>Access and copy your account information</td><td>Submit a request using the contact details in Section 1</td></tr><tr><td><strong>Right to correct and supplement</strong></td><td>Correct inaccurate account information</td><td>Submit a request using the contact details in Section 1</td></tr><tr><td><strong>Right to deletion</strong></td><td>Request deletion under legally prescribed circumstances</td><td>Submit a request using the contact details in Section 1</td></tr><tr><td><strong>Right to withdraw consent</strong></td><td>Withdraw your separate consent to cross-border transfers</td><td>Submit a request using the contact details in Section 1; withdrawal does not affect processing carried out before withdrawal</td></tr></tbody></table><p><strong>Consequences of withdrawing separate consent to cross-border transfers:</strong> Cross-border synchronization is necessary to maintain the Website&#39;s account functionality. Withdrawing your separate consent will therefore make it impossible for us to continue providing the Website&#39;s services to you, and you may choose to stop using the Website. After withdrawal, we will stop synchronizing your information with <code>ets2la.com</code>, but synchronization already completed cannot be retroactively undone.</p><p>We will respond to your rights request within <strong>15 business days</strong> of receipt. In complex cases, the response period may be extended to a reasonable period, and we will inform you accordingly.</p><h3 id="_8-updates-to-this-policy" tabindex="-1">8. Updates to This Policy <a class="header-anchor" href="#_8-updates-to-this-policy" aria-label="Permalink to “8. Updates to This Policy”">​</a></h3><p>We may update this Policy due to changes in laws, service adjustments, or changes in the categories of data processed. The updated Policy will be published on the Website. Material changes—particularly changes to the overseas recipient, additional categories of information transferred overseas, or changes to the purposes of processing—will be <strong>separately highlighted</strong> through a pop-up or an on-site announcement, and we will obtain your consent again where necessary.</p><p>In the event of any discrepancy between the Chinese version of this Policy and any translated version, the <strong>Chinese version</strong> shall prevail.</p><h3 id="_9-contact-and-complaints" tabindex="-1">9. Contact and Complaints <a class="header-anchor" href="#_9-contact-and-complaints" aria-label="Permalink to “9. Contact and Complaints”">​</a></h3><p>If you have any questions about this Policy or wish to exercise any of the rights listed in Section 7, please contact us at:</p><p><strong>Email:</strong> <a href="mailto:1804832964@qq.com" target="_blank" rel="noreferrer">1804832964@qq.com</a></p><p>If you believe that our processing activities have harmed your lawful rights and interests, you may also file a complaint or report with the <strong>cyberspace administration authority of your province</strong>.</p>',97)])])}const u=e(n,[["render",s]]);export{g as __pageData,u as default};
